///     guard let result = result else { return } // no_match -> stay on home
///     // Host routes: open the deep link, fall back to the web URL if it can't be opened.
///     if let ios = result.deeplinkData.iosUrl {
///         UIApplication.shared.open(ios, options: [:]) { success in
///             if !success, let fb = result.deeplinkData.iosFallbackUrl { UIApplication.shared.open(fb) }
